use vstd::prelude::*;

verus! {

struct Interval {
    min: i32,
    max: i32,
}

impl Interval {
    spec fn valid(&self) -> bool {
        self.min < self.max
    }
}

struct ChebyshevPoly {
    coefficients: Seq<i32>,
    domain: Interval,
    window: Interval,
}

fn chebyshev(coef: Vec<i8>) -> (result: ChebyshevPoly)
    requires
        coef.len() > 0,
    ensures
        result.coefficients.len() == coef.len() &&
        forall|i: int| 0 <= i && i < coef.len() as int ==> 
            result.coefficients.index(i) == coef.index(i as usize) as i32 &&
        result.domain.min == -1 &&
        result.domain.max == 1 &&
        result.domain.valid() &&
        result.window.min == -1 &&
        result.window.max == 1 &&
        result.window.valid()
{
    let mut coefficients_seq = Seq::empty();
    let mut idx: usize = 0;
    while idx < coef.len()
        invariant
            idx <= coef.len(),
            coefficients_seq.len() == idx as int,
            forall|i: int| 0 <= i && i < idx as int ==>
                coefficients_seq.index(i) == coef.index(i as usize) as i32,
        decreases coef.len() - idx,
    {
        coefficients_seq = coefficients_seq.push(coef[idx] as i32);
        idx = idx + 1;
    }

    let domain = Interval {
        min: -1,
        max: 1,
    };
    let window = Interval {
        min: -1,
        max: 1,
    };

    ChebyshevPoly {
        coefficients: coefficients_seq,
        domain,
        window,
    }
}

} // verus
